   880   * Backpatch the blocks in 'list' to 'target'.  The 'sense' field indicates
   881   * which of the jt and jf fields has been resolved and which is a pointer
   882   * back to another unresolved block (or nil).  At least one of the fields
   883   * in each block is already resolved.
   884   */
   885  static void
   886  backpatch(struct block *list, struct block *target)
   887  {
   888          struct block *next;
   889
   890          while (list) {
   891                  if (!list->sense) {
   892                          next = JT(list);
   893                          JT(list) = target;
   894                  } else {
   895                          next = JF(list);
   896                          JF(list) = target;
   897                  }
   898                  list = next;
   899          }
   900  }
